1	/**
2	 * GitHub Actions step output helper.
3	 *
4	 * Writes `key=value` pairs to the file referenced by `$GITHUB_OUTPUT` using the
5	 * heredoc delimiter form, which is safe for multi-line values. Shared by the
6	 * action's entry-point scripts so the write pattern lives in one place.
7	 *
8	 * @example
9	 * await setOutput("skip_review", "false");
10	 */
11	import { randomUUID } from "node:crypto";
12	import { appendFile } from "node:fs/promises";
13	
14	/**
15	 * Append a GitHub Actions output variable, using a heredoc delimiter so values
16	 * containing newlines are handled correctly. Warns and no-ops when `GITHUB_OUTPUT`
17	 * is unset (e.g. running outside a GitHub Actions runner).
18	 */
19	export async function setOutput(key: string, value: string): Promise<void> {
20	  const outputFile = process.env.GITHUB_OUTPUT;
21	  if (!outputFile) {
22	    console.warn(`GITHUB_OUTPUT is not set — skipping output "${key}"`);
23	    return;
24	  }
25	
26	  const delimiter = `EOF_${randomUUID().replaceAll("-", "")}`;
27	  await appendFile(outputFile, `${key}<<${delimiter}\n${value}\n${delimiter}\n`);
28	}
