1	/**
2	 * Preflight PR check status polling before AI code review.
3	 * Polls GitHub Check Runs and Commit Statuses APIs until all sibling checks complete.
4	 * Skips review and posts a comment if any check has failed. On a polling timeout it
5	 * posts a comment and fails the job — checks never converged, so a green review
6	 * result would be misleading.
7	 *
8	 * On failed checks this step does NOT post the skip comment itself: it emits the
9	 * failed checks plus an "explain" prompt as step outputs, and the separate
10	 * `runClaude` explain step + `preflightSkipComment.ts` post step assemble and
11	 * post the enriched comment (mirroring the review/react flow). The timeout path,
12	 * which makes no model call, posts its comment inline here and then fails the job.
13	 *
14	 * @example
15	 * GH_TOKEN=xxx REPO=owner/repo PR_NUMBER=123 PR_HEAD_SHA=abc JOB_NAME=review POLL_INTERVAL=10 CHECKS_TIMEOUT=600 PR_AUTHOR=user bun run scripts/preflightChecks.ts
16	 */
17	import {
18	  fetchCheckStatuses,
19	  pollCheckStatuses,
20	  type FailedCheck,
21	} from "@code-assistants/actions-core/checkStatus";
22	import type { Octokit } from "@octokit/rest";
23	
24	import { setOutput } from "./actionsOutput.ts";
25	import { parseRepoEnv } from "./github/githubReview.ts";
26	import { buildExplainPrompt, fetchFailureContext, postSkipComment } from "./skipComment.ts";
27	
28	/** Outcome of the preflight polling loop */
29	type PreflightOutcome =
30	  | { status: "passed" }
31	  | { status: "failed"; failed: FailedCheck[] }
32	  | { status: "timeout"; pendingNames: string[] };
33	
34	/** Preflight configuration parsed from environment */
35	interface PreflightConfig {
36	  octokit: Octokit;
37	  owner: string;
38	  repoName: string;
39	  pullNumber: number;
40	  reviewer: string;
41	  headSha: string;
42	  jobName: string;
43	  pollIntervalMs: number;
44	  timeoutMs: number;
45	  prAuthor: string;
46	}
47	
48	/** Parse and validate preflight-specific environment variables. */
49	function parsePreflightEnv(): PreflightConfig {
50	  const { octokit, owner, repoName, pullNumber, reviewer } = parseRepoEnv();
51	  const headSha = process.env.PR_HEAD_SHA;
52	  const jobName = process.env.JOB_NAME;
53	  const prAuthor = process.env.PR_AUTHOR ?? "there";
54	
55	  if (!headSha || !jobName) {
56	    throw new Error("Missing required environment variables: PR_HEAD_SHA, JOB_NAME");
57	  }
58	
59	  const rawInterval = Number(process.env.POLL_INTERVAL);
60	  const pollIntervalMs =
61	    (Number.isFinite(rawInterval) && rawInterval > 0 ? rawInterval : 10) * 1000;
62	  const rawTimeout = Number(process.env.CHECKS_TIMEOUT);
63	  const timeoutMs = (Number.isFinite(rawTimeout) && rawTimeout > 0 ? rawTimeout : 600) * 1000;
64	
65	  return {
66	    octokit,
67	    owner,
68	    repoName,
69	    pullNumber,
70	    reviewer,
71	    headSha,
72	    jobName,
73	    pollIntervalMs,
74	    timeoutMs,
75	    prAuthor,
76	  };
77	}
78	
79	/**
80	 * Poll until all sibling checks complete or timeout is reached.
81	 * Logs progress on each tick with pending check names and elapsed time.
82	 */
83	async function pollUntilComplete(config: PreflightConfig): Promise<PreflightOutcome> {
84	  const { octokit, owner, repoName, headSha, jobName, pollIntervalMs, timeoutMs } = config;
85	  const timeoutSec = Math.round(timeoutMs / 1000);
86	
87	  const result = await pollCheckStatuses(
88	    () => fetchCheckStatuses(octokit, owner, repoName, headSha, jobName),
89	    {
90	      pollIntervalMs,
91	      timeoutMs,
92	      onPending: (pendingNames, elapsedMs) =>
93	        console.log(
94	          `Waiting for checks: ${pendingNames.join(", ")}... (${Math.round(elapsedMs / 1000)}s / ${timeoutSec}s)`,
95	        ),
96	    },
97	  );
98	
99	  if (result.hasFailed) {
100	    return { status: "failed", failed: result.failed };
101	  }
102	  if (result.allCompleted) {
103	    return { status: "passed" };
104	  }
105	
106	  return { status: "timeout", pendingNames: result.pendingNames };
107	}
108	
109	/** Build comment for polling timeout. */
110	function buildTimeoutComment(author: string, pendingNames: string[], timeoutMin: number): string {
111	  const list = pendingNames.map((name) => `- ${name}`).join("\n");
112	
113	  return `@${author}, I've been waiting for your checks for ${timeoutMin} minutes and they still haven't finished ⏰
114	
115	Still pending:
116	${list}
117	
118	I have better things to do than wait around. Fix your CI and re-request review when you're ready 💅
119	
120	_Code Review skipped 😢_`;
121	}
122	
123	/**
124	 * Fetch failure annotations, build the explain prompt, and emit the outputs the
125	 * separate `runClaude` explain step consumes. `explain` is set to `true` only
126	 * when at least one failed check carries annotations (so there is something to
127	 * explain) and the prompt is written; otherwise the explain step is skipped and
128	 * the comment degrades to links-only — a skip is never blocked on the enhancement.
129	 */
130	async function emitExplainContext(config: PreflightConfig, failed: FailedCheck[]): Promise<void> {
131	  try {
132	    const context = await fetchFailureContext(
133	      config.octokit,
134	      config.owner,
135	      config.repoName,
136	      failed,
137	    );
138	    if (Object.keys(context).length === 0) {
139	      await setOutput("explain", "false");
140	      return;
141	    }
142	
143	    const prompt = buildExplainPrompt(failed, context);
144	    const promptFile = `${process.env.RUNNER_TEMP ?? "/tmp"}/preflight-explain-prompt.txt`;
145	    await Bun.write(promptFile, prompt);
146	    await setOutput("explain_prompt_file", promptFile);
147	    await setOutput("explain", "true");
148	  } catch (error) {
149	    // Fail open: never block a skip on the enhancement. Log error.message only —
150	    // not the raw response/headers — so auth material can't leak into public logs.
151	    const message = error instanceof Error ? error.message : String(error);
152	    console.log(`::warning title=Preflight explain context failed::${message}`);
153	    await setOutput("explain", "false");
154	  }
155	}
156	
157	// Main execution
158	try {
159	  const config = parsePreflightEnv();
160	  console.log(
161	    `Preflight: polling checks for ${config.headSha.slice(0, 7)} every ${config.pollIntervalMs / 1000}s (timeout: ${config.timeoutMs / 1000}s)`,
162	  );
163	
164	  const outcome = await pollUntilComplete(config);
165	
166	  if (outcome.status === "passed") {
167	    console.log("✓ All checks passed, proceeding with review");
168	    await setOutput("skip_review", "false");
169	  } else if (outcome.status === "failed") {
170	    const { failed } = outcome;
171	    console.log(`✗ Failed checks: ${failed.map((f) => f.name).join(", ")}`);
172	    await setOutput("skip_review", "true");
173	    await setOutput("has_failures", "true");
174	    await setOutput("failed_json", JSON.stringify(failed));
175	    await emitExplainContext(config, failed);
176	  } else {
177	    const timeoutMin = Math.round(config.timeoutMs / 60_000);
178	    console.log(`✗ Timeout after ${timeoutMin}min, pending: ${outcome.pendingNames.join(", ")}`);
179	    const comment = buildTimeoutComment(config.prAuthor, outcome.pendingNames, timeoutMin);
180	    await postSkipComment(
181	      config.octokit,
182	      config.owner,
183	      config.repoName,
184	      config.pullNumber,
185	      config.reviewer,
186	      comment,
187	    );
188	    await setOutput("skip_review", "true");
189	    // A checks timeout means CI never converged, so the review could not run — fail
190	    // the job instead of reporting a misleading green. Set process.exitCode rather
191	    // than throwing (a throw hits the fail-open catch below and would proceed with
192	    // review) or calling process.exit (which would cut off pending log flushes).
193	    console.log(
194	      `::error title=Preflight checks timed out::${outcome.pendingNames.length} check(s) still pending after ${timeoutMin}min`,
195	    );
196	    process.exitCode = 1;
197	  }
198	} catch (error) {
199	  // Fail open so a preflight glitch never blocks review — but surface it as a
200	  // GitHub Actions warning annotation so the silent proceed is visible in the run.
201	  const message = error instanceof Error ? error.message : String(error);
202	  console.log(`::warning title=Preflight failed open::${message}`);
203	  console.error("Preflight check error (fail-open, proceeding with review):", error);
204	  await setOutput("skip_review", "false");
205	}
