1	/**
2	 * Shared GitHub review operations for PR review submission and comment reaction scripts.
3	 * Provides review thread fetching, resolution, and Octokit initialization.
4	 *
5	 * @example
6	 * import { fetchReviewThreads, resolveThread, parseRepoEnv } from "./github/githubReview.ts";
7	 */
8	import { createOctokit } from "@code-assistants/actions-core/createOctokit";
9	import type { Octokit } from "@octokit/rest";
10	
11	import { stripReviewTips } from "../reviewTip.ts";
12	import { stripLegacyUsageHint, stripRunSummaryFooter } from "../runSummaryFooter.ts";
13	
14	/** GitHub PR review event type */
15	export type ReviewEvent = "APPROVE" | "REQUEST_CHANGES" | "COMMENT";
16	
17	/** Flattened review thread from GraphQL response */
18	export interface ReviewThread {
19	  id: string;
20	  path: string;
21	  line: number | null;
22	  isOutdated: boolean;
23	  isResolved: boolean;
24	  firstCommentAuthor: string | null;
25	  firstCommentBody: string;
26	  firstCommentReviewId: string | null;
27	}
28	
29	/** Parsed repository environment configuration */
30	export interface RepoEnv {
31	  octokit: Octokit;
32	  owner: string;
33	  repoName: string;
34	  pullNumber: number;
35	  reviewer: string;
36	}
37	
38	/** Single review-thread node as returned by the GraphQL query */
39	interface ReviewThreadNode {
40	  id: string;
41	  path: string;
42	  line: number | null;
43	  isOutdated: boolean;
44	  isResolved: boolean;
45	  comments: {
46	    nodes: Array<{
47	      author: { login: string } | null;
48	      body: string;
49	      pullRequestReview: { id: string } | null;
50	    }>;
51	  };
52	}
53	
54	/** GraphQL response shape for review threads query */
55	interface ReviewThreadsResponse {
56	  repository: {
57	    pullRequest: {
58	      reviewThreads: {
59	        nodes: ReviewThreadNode[];
60	        pageInfo: { hasNextPage: boolean; endCursor: string | null };
61	      };
62	    };
63	  };
64	}
65	
66	/** Maps verdict string to GitHub review event */
67	export const verdictToEvent: Record<string, ReviewEvent> = {
68	  approve: "APPROVE",
69	  requestChanges: "REQUEST_CHANGES",
70	  comment: "COMMENT",
71	};
72	
73	/**
74	 * Normalize a review/comment body for dedup comparison. Strips per-line trailing
75	 * whitespace and collapses 3+ consecutive newlines to two, but preserves line
76	 * breaks — so bodies that differ structurally are NOT treated as identical (the
77	 * old collapse-all-whitespace approach silently dropped genuinely different reviews).
78	 */
79	export function normalizeBody(body: string): string {
80	  return body
81	    .replaceAll(/[ \t]+$/gm, "")
82	    .replaceAll(/\n{3,}/g, "\n\n")
83	    .trim();
84	}
85	
86	/**
87	 * Canonical dedup key for review-body comparison: strips the run-varying
88	 * summary footer, any review-tip block, and the retired always-on usage hint
89	 * still present in pre-hotfix review bodies, then normalizes whitespace — so
90	 * two reviews differing only in metrics, a rolled tip, or the legacy hint
91	 * compare as identical. Tip blocks are consumed whole (marker-shaped) before
92	 * the legacy matcher runs. Every duplicate-suppression comparison must go
93	 * through this one composition — a site applying its own subset silently
94	 * defeats dedup.
95	 */
96	export function reviewDedupKey(body: string): string {
97	  return normalizeBody(stripLegacyUsageHint(stripRunSummaryFooter(stripReviewTips(body))));
98	}
99	
100	/** Minimal shape of a submitted review needed for dedup comparison. */
101	export interface BotReviewSummary {
102	  body: string | null;
103	  state?: string;
104	}
105	
106	/**
107	 * Return the most recent non-pending review authored by the bot, or undefined.
108	 * Used both for the initial dedup check and the last-write guard re-read
109	 * immediately before submitting, which narrows the concurrent-duplicate window.
110	 */
111	export async function getLastBotReview(
112	  octokit: Octokit,
113	  owner: string,
114	  repo: string,
115	  pullNumber: number,
116	  reviewer: string
117	): Promise<BotReviewSummary | undefined> {
118	  const { data: reviews } = await octokit.rest.pulls.listReviews({
119	    owner,
120	    repo,
121	    pull_number: pullNumber,
122	  });
123	  return reviews.filter((r) => r.user?.login === reviewer && r.state !== "PENDING").at(-1);
124	}
125	
126	/**
127	 * All non-pending review bodies the bot has posted on a PR, oldest first.
128	 * Paginates past the 30-per-page default so the review-tip no-repeat guard
129	 * sees every prior tip marker even on long-lived PRs.
130	 */
131	export async function listBotReviewBodies(
132	  octokit: Octokit,
133	  owner: string,
134	  repo: string,
135	  pullNumber: number,
136	  reviewer: string
137	): Promise<string[]> {
138	  const reviews = await octokit.paginate(octokit.rest.pulls.listReviews, {
139	    owner,
140	    repo,
141	    pull_number: pullNumber,
142	    per_page: 100,
143	  });
144	  return reviews
145	    .filter((review) => review.user?.login === reviewer && review.state !== "PENDING")
146	    .map((review) => review.body ?? "");
147	}
148	
149	/**
150	 * Parse and validate required environment variables, initialize Octokit.
151	 * Throws if GH_TOKEN, REPO, PR_NUMBER, or REVIEWER are missing or invalid.
152	 */
153	export function parseRepoEnv(): RepoEnv {
154	  const token = process.env.GH_TOKEN;
155	  const repo = process.env.REPO;
156	  const prNumber = process.env.PR_NUMBER;
157	  const reviewer = process.env.REVIEWER;
158	
159	  if (!token || !repo || !prNumber || !reviewer) {
160	    throw new Error("Missing required environment variables: GH_TOKEN, REPO, PR_NUMBER, REVIEWER");
161	  }
162	
163	  const [owner, repoName] = repo.split("/");
164	  if (!owner || !repoName) {
165	    throw new Error(`Invalid REPO format: ${repo}. Expected owner/repo`);
166	  }
167	
168	  return {
169	    octokit: createOctokit(token),
170	    owner,
171	    repoName,
172	    pullNumber: Number(prNumber),
173	    reviewer,
174	  };
175	}
176	
177	/** Flatten a GraphQL review-thread node into a {@link ReviewThread}. */
178	function mapThreadNode(node: ReviewThreadNode): ReviewThread {
179	  return {
180	    id: node.id,
181	    path: node.path,
182	    line: node.line,
183	    isOutdated: node.isOutdated,
184	    isResolved: node.isResolved,
185	    firstCommentAuthor: node.comments.nodes[0]?.author?.login ?? null,
186	    firstCommentBody: node.comments.nodes[0]?.body ?? "",
187	    firstCommentReviewId: node.comments.nodes[0]?.pullRequestReview?.id ?? null,
188	  };
189	}
190	
191	/** Fetch a single page of review threads. Explicit return type pins inference. */
192	async function fetchReviewThreadPage(
193	  octokit: Octokit,
194	  owner: string,
195	  repo: string,
196	  pullNumber: number,
197	  cursor: string | null
198	): Promise<ReviewThreadsResponse> {
199	  const query = `
200	    query($owner: String!, $repo: String!, $number: Int!, $cursor: String) {
201	      repository(owner: $owner, name: $repo) {
202	        pullRequest(number: $number) {
203	          reviewThreads(first: 100, after: $cursor) {
204	            nodes {
205	              id
206	              path
207	              line
208	              isOutdated
209	              isResolved
210	              comments(first: 1) {
211	                nodes {
212	                  author { login }
213	                  body
214	                  pullRequestReview { id }
215	                }
216	              }
217	            }
218	            pageInfo { hasNextPage endCursor }
219	          }
220	        }
221	      }
222	    }
223	  `;
224	
225	  return octokit.graphql<ReviewThreadsResponse>(query, { owner, repo, number: pullNumber, cursor });
226	}
227	
228	/**
229	 * Fetch all review threads for a PR via GraphQL, paginating past the 100-node
230	 * page so long-lived PRs don't silently drop threads from resolution logic.
231	 */
232	export async function fetchReviewThreads(
233	  octokit: Octokit,
234	  owner: string,
235	  repo: string,
236	  pullNumber: number
237	): Promise<ReviewThread[]> {
238	  const threads: ReviewThread[] = [];
239	  let cursor: string | null = null;
240	
241	  for (;;) {
242	    const page: ReviewThreadsResponse = await fetchReviewThreadPage(
243	      octokit,
244	      owner,
245	      repo,
246	      pullNumber,
247	      cursor
248	    );
249	    const { reviewThreads } = page.repository.pullRequest;
250	    threads.push(...reviewThreads.nodes.map(mapThreadNode));
251	    if (!reviewThreads.pageInfo.hasNextPage) break;
252	    cursor = reviewThreads.pageInfo.endCursor;
253	  }
254	
255	  return threads;
256	}
257	
258	/**
259	 * Resolve a single review thread by its GraphQL node ID.
260	 */
261	export async function resolveThread(octokit: Octokit, threadId: string): Promise<void> {
262	  await octokit.graphql(
263	    `
264	      mutation($threadId: ID!) {
265	        resolveReviewThread(input: { threadId: $threadId }) {
266	          thread { isResolved }
267	        }
268	      }
269	    `,
270	    { threadId }
271	  );
272	}
273	
274	/**
275	 * Unresolve a single review thread by its GraphQL node ID.
276	 * Used to reopen threads that GitHub auto-resolves on APPROVE reviews.
277	 */
278	export async function unresolveThread(octokit: Octokit, threadId: string): Promise<void> {
279	  await octokit.graphql(
280	    `
281	      mutation($threadId: ID!) {
282	        unresolveReviewThread(input: { threadId: $threadId }) {
283	          thread { isResolved }
284	        }
285	      }
286	    `,
287	    { threadId }
288	  );
289	}
