1	/**
2	 * Shared PR check-status aggregation across the repository's GitHub Actions.
3	 *
4	 * Merges GitHub's two independent signals for a commit — Check Runs
5	 * (`checks.listForRef`) and Commit Statuses (`repos.getCombinedStatusForRef`) —
6	 * into a single verdict, deduplicating superseded check runs and excluding the
7	 * caller's own check by normalized name. Used by `code-review-action`'s
8	 * preflight poll loop and by `release-automerge`'s one-shot merge gate.
9	 *
10	 * @example
11	 *   const result = await fetchCheckStatuses(octokit, owner, repo, headSha, jobName);
12	 *   if (result.hasFailed || !result.allCompleted) return; // not green yet
13	 */
14	import type { Octokit } from "@octokit/rest";
15	
16	/**
17	 * A single failed check, carrying a link to its run log so consumers can render
18	 * an actionable reference instead of a bare name.
19	 */
20	export interface FailedCheck {
21	  /** Display name: a check-run name or a commit-status context. */
22	  name: string;
23	  /**
24	   * Link to the failing run's logs — a check-run `details_url`/`html_url`, or a
25	   * commit-status `target_url`. Null when GitHub exposes none.
26	   */
27	  url: string | null;
28	  /** Check-run id for fetching annotations; null for commit statuses (no annotations). */
29	  checkRunId: number | null;
30	}
31	
32	/** Aggregated check status result from both GitHub APIs. */
33	export interface CheckResult {
34	  allCompleted: boolean;
35	  hasFailed: boolean;
36	  failed: FailedCheck[];
37	  pendingNames: string[];
38	}
39	
40	const failedConclusions = new Set(["failure", "timed_out"]);
41	const failedStatuses = new Set(["failure", "error"]);
42	
43	/**
44	 * Normalize a check name for self-exclusion comparison.
45	 * Strips non-alphanumeric characters so "code-review" matches "Code Review".
46	 */
47	export function normalizeCheckName(name: string): string {
48	  return name.toLowerCase().replaceAll(/[^a-z0-9]/g, "");
49	}
50	
51	/**
52	 * Deduplicate check runs by name, keeping only the most recent run per name.
53	 * GitHub's Check Runs API returns all runs including superseded ones from previous pushes.
54	 * Uses the auto-incrementing `id` field as the recency indicator.
55	 */
56	export function deduplicateCheckRuns<T extends { id: number; name: string }>(runs: T[]): T[] {
57	  const latestByName = new Map<string, T>();
58	
59	  for (const run of runs) {
60	    const existing = latestByName.get(run.name);
61	    if (!existing || run.id > existing.id) {
62	      latestByName.set(run.name, run);
63	    }
64	  }
65	
66	  return [...latestByName.values()];
67	}
68	
69	/**
70	 * Fetch and aggregate check statuses from both Check Runs and Commit Status APIs.
71	 * Excludes the current job's own check run by normalized name comparison.
72	 */
73	export async function fetchCheckStatuses(
74	  octokit: Octokit,
75	  owner: string,
76	  repo: string,
77	  ref: string,
78	  jobName: string,
79	): Promise<CheckResult> {
80	  const normalizedJobName = normalizeCheckName(jobName);
81	
82	  const [checkRuns, commitStatus] = await Promise.all([
83	    octokit.paginate(octokit.rest.checks.listForRef, { owner, repo, ref, per_page: 100 }),
84	    octokit.rest.repos.getCombinedStatusForRef({ owner, repo, ref }),
85	  ]);
86	
87	  const allSiblingRuns = checkRuns.filter(
88	    (run) => normalizeCheckName(run.name) !== normalizedJobName,
89	  );
90	  // A cancelled run carries no pass/fail/pending signal (e.g. a path-filter-skipped
91	  // job, or a run superseded by a newer push). Excluding cancelled runs entirely —
92	  // rather than treating a cancelled-only check as pending — keeps a permanently
93	  // cancelled check from blocking the gate forever. The one-shot merge gate has no
94	  // poll loop to recover, and GitHub's merge API still enforces genuinely required
95	  // checks regardless.
96	  const siblingRuns = deduplicateCheckRuns(
97	    allSiblingRuns.filter((run) => run.conclusion !== "cancelled"),
98	  );
99	
100	  const pendingRuns = siblingRuns
101	    .filter((run) => run.status !== "completed")
102	    .map((run) => run.name);
103	  const failedRuns = siblingRuns
104	    .filter((run) => run.status === "completed" && failedConclusions.has(run.conclusion ?? ""))
105	    .map((run) => ({
106	      name: run.name,
107	      url: run.details_url ?? run.html_url ?? null,
108	      checkRunId: run.id,
109	    }));
110	
111	  const pendingStatuses = commitStatus.data.statuses
112	    .filter((s) => s.state === "pending")
113	    .map((s) => s.context);
114	  const failedCommitStatuses = commitStatus.data.statuses
115	    .filter((s) => failedStatuses.has(s.state))
116	    .map((s) => ({ name: s.context, url: s.target_url ?? null, checkRunId: null }));
117	
118	  const allPending = [...pendingRuns, ...pendingStatuses];
119	  const allFailed: FailedCheck[] = [...failedRuns, ...failedCommitStatuses];
120	
121	  return {
122	    allCompleted: allPending.length === 0,
123	    hasFailed: allFailed.length > 0,
124	    failed: allFailed,
125	    pendingNames: allPending,
126	  };
127	}
128	
129	/** Options for {@link pollCheckStatuses}. */
130	export interface PollCheckOptions {
131	  /** Delay between polls, in milliseconds. */
132	  pollIntervalMs: number;
133	  /** Wall-clock budget before giving up, in milliseconds. */
134	  timeoutMs: number;
135	  /** Sleep implementation; injected in tests. Defaults to a `setTimeout` promise. */
136	  sleep?: (ms: number) => Promise<void>;
137	  /** Monotonic clock in milliseconds; injected in tests. Defaults to `Date.now`. */
138	  now?: () => number;
139	  /** Invoked once per still-pending tick before sleeping (e.g. to log progress). */
140	  onPending?: (pendingNames: string[], elapsedMs: number) => void;
141	}
142	
143	const defaultSleep = (ms: number): Promise<void> =>
144	  new Promise((resolve) => {
145	    setTimeout(resolve, ms);
146	  });
147	
148	/**
149	 * Poll a {@link CheckResult} source until checks fail, all complete, or the
150	 * timeout elapses. Elapsed time is measured on a wall clock (`now()`), so the
151	 * latency of each status fetch counts toward the cap — the loop cannot overrun
152	 * the budget by the aggregate fetch time. Returns the final result; the caller
153	 * decides how to treat a still-pending (timed-out) result.
154	 *
155	 * `fetchStatus`, `sleep`, and `now` are injectable so the loop is testable
156	 * without real timers or a GitHub client.
157	 *
158	 * @example
159	 *   const result = await pollCheckStatuses(
160	 *     () => fetchCheckStatuses(octokit, owner, repo, sha, jobName),
161	 *     { pollIntervalMs: 15_000, timeoutMs: 480_000 },
162	 *   );
163	 */
164	export async function pollCheckStatuses(
165	  fetchStatus: () => Promise<CheckResult>,
166	  options: PollCheckOptions,
167	): Promise<CheckResult> {
168	  const sleep = options.sleep ?? defaultSleep;
169	  const now = options.now ?? Date.now;
170	  const start = now();
171	
172	  let result = await fetchStatus();
173	  let elapsed = now() - start;
174	  while (!result.hasFailed && !result.allCompleted && elapsed < options.timeoutMs) {
175	    options.onPending?.(result.pendingNames, elapsed);
176	    await sleep(options.pollIntervalMs);
177	    result = await fetchStatus();
178	    elapsed = now() - start;
179	  }
180	
181	  return result;
182	}
