546	/** True when an assistant message content array holds at least one `tool_use` block. */
547	function hasToolUseBlock(content: unknown): boolean {
548	  if (!Array.isArray(content)) return false;
549	  return content.some(
550	    (block) =>
551	      typeof block === "object" &&
552	      block !== null &&
553	      (block as Record<string, unknown>).type === "tool_use"
554	  );
555	}
