557	/**
558	 * Count assistant turns that issued at least one tool call — i.e. model→tool
559	 * round-trips. A single turn with several parallel `tool_use` blocks counts once.
560	 */
561	export function countToolRoundTrips(messages: unknown[]): number {
562	  let count = 0;
563	  for (const message of messages) {
564	    if (typeof message !== "object" || message === null) continue;
565	    const record = message as Record<string, unknown>;
566	    if (record.type !== "assistant") continue;
567	    if (hasToolUseBlock((record.message as { content?: unknown } | undefined)?.content)) count += 1;
568	  }
569	  return count;
570	}
