572	/** Token and cost usage extracted from the SDK `result` message. */
573	export interface UsageSummary {
574	  tokensIn: number;
575	  tokensOut: number;
576	  cacheReadTokens: number;
577	  cacheCreationTokens: number;
578	  costUsd: number;
579	  numTurns: number;
580	}
581	
582	/** Extract usage/cost fields from the SDK `result` message, defaulting absent values to 0. */
583	export function extractUsage(resultMessage: Record<string, unknown> | undefined): UsageSummary {
584	  const usage = (resultMessage?.usage ?? {}) as Record<string, unknown>;
585	  const toNumber = (value: unknown): number =>
586	    typeof value === "number" && Number.isFinite(value) ? value : 0;
587	
588	  const cacheReadTokens = toNumber(usage.cache_read_input_tokens);
589	  const cacheCreationTokens = toNumber(usage.cache_creation_input_tokens);
590	
591	  return {
592	    // Total input the model consumed: fresh + cache-read + cache-creation. Reading
593	    // only `input_tokens` reports the tiny uncached residual (an implausible ~9
594	    // under heavy prompt caching); the breakdown stays in the cache fields below.
595	    tokensIn: toNumber(usage.input_tokens) + cacheReadTokens + cacheCreationTokens,
596	    tokensOut: toNumber(usage.output_tokens),
597	    cacheReadTokens,
598	    cacheCreationTokens,
599	    costUsd: toNumber(resultMessage?.total_cost_usd),
600	    numTurns: toNumber(resultMessage?.num_turns),
601	  };
602	}
