609	/**
610	 * Build the structured per-run summary: mode, model, phase timings, token
611	 * usage, cost, and tool round-trips. Returns the snake_case-keyed object that
612	 * is logged as a single line — separated from logging so the field mapping is
613	 * unit-testable. The model comes from the SDK init message (what actually
614	 * ran), with the configured model as the fallback.
615	 */
616	export function buildRunSummary(
617	  mode: string,
618	  messages: unknown[],
619	  timings: PhaseTimings,
620	  fallbackModel: string
621	): Record<string, number | string> {
622	  const usage = extractUsage(findResultMessage(messages));
623	
624	  return {
625	    mode,
626	    model: findInitModel(messages) ?? fallbackModel,
627	    model_ms: timings.modelMs,
628	    tokens_in: usage.tokensIn,
629	    tokens_out: usage.tokensOut,
630	    cache_read_tokens: usage.cacheReadTokens,
631	    cache_creation_tokens: usage.cacheCreationTokens,
632	    cost_usd: usage.costUsd,
633	    num_turns: usage.numTurns,
634	    tool_round_trips: countToolRoundTrips(messages),
635	  };
636	}
