638	/**
639	 * Emit GitHub Actions outputs from the collected messages, flag long-running
640	 * sessions, and exit non-zero when the final result subtype isn't "success".
641	 */
642	async function emitOutputs(
643	  log: pino.Logger,
644	  outputFilePath: string,
645	  messages: unknown[]
646	): Promise<void> {
647	  const resultMessage = findResultMessage(messages);
648	
649	  const structuredOutput = resultMessage?.structured_output;
650	  const conclusion = (resultMessage?.subtype as string) ?? "error";
651	  const durationMs = Number(resultMessage?.duration_ms ?? 0);
652	
